const std = @import("std");

pub const RecognitionError = error{
    InvalidRowCount,
    InvalidColumnCount,
};

const digits = [_][4][]const u8{
    [4][]const u8{
        " _ ", //
        "| |", // 0
        "|_|", //
        "   ", //
    },
    [4][]const u8{
        "   ", //
        "  |", // 1
        "  |", //
        "   ", //
    },
    [4][]const u8{
        " _ ", //
        " _|", // 2
